Problem Description:
The following adder-subtractor with zero flag doesn't work. Fix the bug(s).

// synthesis verilog_input_version verilog_2001
// module top_module ( 
//     input do_sub,
//     input [7:0] a,
//     input [7:0] b,
//     output reg [7:0] out,
//     output reg result_is_zero
// );//

//     always @(*) begin
//         case (do_sub)
//           0: out = a+b;
//           1: out = a-b;
//         endcase

//         if (~out)
//             result_is_zero = 1;
//     end

// endmodule

module top_module (
	input do_sub,
	input [7:0] a,
	input [7:0] b,
	output reg [7:0] out,
	output reg result_is_zero
);

Erroneous Implementation:

module top_module (
input wire clk,
input wire do_sub,
input wire [7:0] a,
input wire [7:0] b,
output reg [7:0] out,
output reg result_is_zero
);
always @(posedge clk) begin
case (do_sub)
0: out <= a + b;
1: out <= a - b;
endcase
if (out == 0)
result_is_zero <= 1;
else
result_is_zero <= 0;
end
endmodule

Feedback:
bugs_addsubz2.sv:133: warning: Instantiating module top_module with dangling input port 1 (clk) floating.

